"use client";

import { useState, useTransition } from "react";

import { Explanation } from "@/components/explanation";
import { TranslateIcon } from "@/components/icons";
import type { Explanation as ExplanationRow } from "@/db/schema";

import { translateAction } from "./actions";
import { usePostTranslation } from "./post-translation";

type ExplanationPanelProps = {
  termId: string;
  /** `terms.position`: the word's tab number. */
  position: number;
  headword: string;
  surface: string;
  english: ExplanationRow | null;
  /** Already generated by an earlier click (read from the database), or null. */
  french: ExplanationRow | null;
};

/**
 * One word's explanation with the Translate toggle (8.2, F9, X-03, mockups
 * 02-D / 02-M). A single button: "Translate" shows the French version,
 * "Show English" goes back.
 *
 * The first click on a word without a French version asks the server, which
 * generates and stores it (Claude call #3); the button shows "Translating…"
 * meanwhile. Every later click only switches what is shown, with no request
 * at all. The French version is also in the page data after a reload, so a
 * word is translated once, ever (D-09).
 *
 * Which words are in French is kept in the page's translation state, so the
 * post card can show the French post text (8.3) while this word is on screen
 * in French. The first Translate of the post also brings that French text,
 * with the French words of each term marked (8.4). A post translated before
 * that has its text regenerated on its next Translate, once.
 */
export function ExplanationPanel({
  termId,
  position,
  headword,
  surface,
  english,
  french: initialFrench,
}: ExplanationPanelProps) {
  const [french, setFrench] = useState(initialFrench);
  const translation = usePostTranslation();
  const showFrench = translation?.isFrench(position) ?? false;
  const setShowFrench = (shown: boolean) => translation?.setFrench(position, shown);
  const [error, setError] = useState<string | null>(null);
  const [translating, startTranslating] = useTransition();

  function toggle() {
    setError(null);
    if (showFrench) return setShowFrench(false);
    // A word translated before 8.4 still asks once if the post's French text has no marks yet.
    if (french && !translation?.textNeedsRefresh) return setShowFrench(true);

    startTranslating(async () => {
      let result: Awaited<ReturnType<typeof translateAction>>;
      try {
        result = await translateAction(termId);
      } catch {
        result = { ok: false, error: "The translation failed. Check your connection." };
      }
      if (result.ok) {
        setFrench(result.explanation);
        translation?.receiveTextFr(result.textFr);
        setShowFrench(true);
      } else {
        setError(result.error);
      }
    });
  }

  return (
    <>
      <Explanation
        headword={headword}
        surface={surface}
        explanation={showFrench ? french : english}
      />

      {english ? (
        <div className="mt-8 border-t border-line pt-6 sm:pt-7">
          <button
            type="button"
            onClick={toggle}
            disabled={translating}
            aria-pressed={showFrench}
            className={`flex h-12 w-full items-center justify-center gap-2.5 rounded-full border px-6 font-bold transition disabled:opacity-75 sm:h-11 sm:w-auto ${
              showFrench
                ? "border-gold/45 bg-gold/12 text-gold hover:bg-gold/18"
                : "border-line-strong text-fg hover:bg-surface-3"
            }`}
          >
            {translating ? (
              <span aria-hidden="true" className="spinner block size-4.5" />
            ) : (
              <TranslateIcon size={18} />
            )}
            {translating ? "Translating…" : showFrench ? "Show English" : "Translate"}
          </button>
          <p role="alert" className="mt-3 text-sm font-medium text-red-400 empty:hidden">
            {error}
          </p>
        </div>
      ) : null}
    </>
  );
}
